style.css:
@-moz-document url-prefix("https://www.baidu.com/s?"), url-prefix("https://www.baidu.com") {
/* 默认样式 */
.s_form,
#s_tab_inner,
#wrapper_wrapper {
  margin-left: 0 !important;
}
.tag-scroll_3EMBO {
  margin-left: 0 !important;
}

/* 1231px - 1500px */
@media only screen and (min-width: 1231px) and (max-width: 1500px) {
  .s_form,
  #s_tab_inner,
  #wrapper_wrapper {
    margin-left: 15% !important;
  }
  .tag-scroll_3EMBO {
    margin-left: 25% !important;
  }
}

/* 1501px - 1920px */
@media only screen and (min-width: 1501px) and (max-width: 1920px) {
  .s_form,
  #s_tab_inner,
  #wrapper_wrapper {
    margin-left: 18% !important;
  }
  .tag-scroll_3EMBO {
    margin-left: 30% !important;
  }
}

/* >= 1921px */
@media only screen and (min-width: 1921px) {
  .s_form,
  #s_tab_inner,
  #wrapper_wrapper {
    margin-left: 0% !important;
  }
  .tag-scroll_3EMBO {
    margin-left: 33% !important;
  }
}

/* 去掉侧边新闻 */
.FYB_RD {
  display: none !important;	    
}
}
